 hours : 12; // the hour '0' should be '12'\nminutes = minutes < 10 ? '0' + minutes : minutes;\nconst strTime = hours + ':' + minutes + ' ' + ampm;\ndocument.getElementById('currentTime').innerText = strTime;\n}\nsetInterval(updateTime, 1000);\nupdateTime();\n*/\n// Initialize Chart.js for Weekly Activity\nconst ctx = document.getElementById('activityChart').getContext('2d');\n// Create gradient for bars\nconst gradientBlue = ctx.createLinearGradient(0, 0, 0, 150);\ngradientBlue.addColorStop(0, '#3B82F6'); // Top color (accentBlue)\ngradientBlue.addColorStop(1, 'rgba(59, 130, 246, 0.1)'); // Bottom color\nconst gradientHighlighted = ctx.createLinearGradient(0, 0, 0, 150);\ngradientHighlighted.addColorStop(0, '#6366F1'); // Top color (indigo)\ngradientHighlighted.addColorStop(1, '#3B82F6'); // Bottom color\nnew Chart(ctx, {\ntype: 'bar',\ndata: {\nlabels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],\ndatasets: [{\nlabel: 'Hours',\ndata: [3.5, 3.2, 4.0, 3.8, 5.0, 7.8, 4.2],\nbackgroundColor: function(context) {\nconst index = context.dataIndex;\n// Highlight Saturday (index 5)\nreturn index === 5 ? gradientHighlighted : gradientBlue;\n},\nborderRadius: 20,\nborderSkipped: false,\nbarThickness: 8,\nhoverBackgroundColor: gradientHighlighted\n}]\n},\noptions: {\nresponsive: true,\nmaintainAspectRatio: false,\nplugins: {\nlegend: {\ndisplay: false\n},\ntooltip: {\nenabled: false // Custom tooltip rendered in HTML to match design exactly\n}\n},\nscales: {\ny: {\ndisplay: false,\nbeginAtZero: true,\nmax: 10\n},\nx: {\ngrid: {\ndisplay: false,\ndrawBorder: false\n},\nticks: {\ncolor: '#94A3B8', // textSecondary\nfont: {\nsize: 10,\nfamily: \"'Inter', sans-serif\"\n},\npadding: 10\n},\nborder: {\ndisplay: false\n}\n}\n},\nanimation: {\nduration: 1500,\neasing: 'easeOutQuart'\n}\n}\n});\n// Add simple interaction to sidebar icons\nconst sidebarIcons = document.querySelectorAll('.sidebar-icon');\nsidebarIcons.forEach(icon => {\nicon.addEventListener('click', function() {\nsidebarIcons.forEach(i => i.classList.remove('active'));\nthis.classList.add('active');\n});\n});\n});\n</script></body></html>"},{"id":"real-login","name":"Login / portal entry","category":"login","tags":["login","sign in","portal","auth","account","password","secure"],"blurb":"The uploaded glassmorphism login — a secure entry screen for any portal we sell.","source":"LOGIN-PAGE/glassmorphism_login_ui.html","html":"<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"><title>Glassmorphism Login</title><style>\nbody {\nfont-family: 'Inter', sans-serif;\n}\n/* Brick wall background texture simulation */\n.brick-wall {\nbackground-color: #0f172a;\nbackground-image:\nlinear-gradient(335deg, rgba(30, 58, 138, 0.6) 0%, rgba(15, 23, 42, 0.9) 100%),\nrepeating-linear-gradient(0deg, transparent, transparent 40px, rgba(0, 0, 0, 0.3) 40px, rgba(0, 0, 0, 0.3) 42px),\nrepeating-linear-gradient(90deg, transparent, transparent 80px, rgba(0, 0, 0, 0.2) 80px, rgba(0, 0, 0, 0.2) 82px);\n}\n/* Spotlight glow effect */\n.spotlight {\nbackground: radial-gradient(circle at 50% 0%, rgba(251, 191, 36, 0.45) 0%, rgba(251, 191, 36, 0.1) 35%, transparent 70%);\n}\n</style><style data-tailwind-compiled>\n*,:after,:before{--tw-border-spacing-x:0;--tw-border-spacing-y:0;--tw-translate-x:0;--tw-translate-y:0;--tw-rotate:0;--tw-skew-x:0;--tw-skew-y:0;--tw-scale-x:1;--tw-scale-y:1;--tw-pan-x: ;--tw-pan-y: ;--tw-pinch-zoom: ;--tw-scroll-snap-strictness:proximity;--tw-gradient-from-position: ;--tw-gradient-via-position: ;--tw-gradient-to-position: ;--tw-ordinal: ;--tw-slashed-zero: ;--tw-numeric-figure: ;--tw-numeric-spacing: ;--tw-numeric-fraction: ;--tw-ring-inset: ;--tw-ring-offset-width:0px;--tw-ring-offset-color:#fff;--tw-ring-color:rgba(59,130,246,.5);--tw-ring-offset-shadow:0 0 #0000;--tw-ring-shadow:0 0 #0000;--tw-shadow:0 0 #0000;--tw-shadow-colored:0 0 #0000;--tw-blur: ;--tw-brightness: ;--tw-contrast: ;--t